{
  "name": "{projectName}",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --port {port}",
    "build": "vue-tsc && vite build",
    "preview": "vite preview",
    "test": "vitest run"
  },
  "dependencies": {
    "pinia": "^2.1.7",
    "vue": "^3.4.31",
    "vue-router": "^4.4.0"
  },
  "devDependencies": {
    "@vitejs/plugin-vue": "^5.0.5",
    "@vue/test-utils": "^2.4.6",
    "jsdom": "^24.1.0",
    "typescript": "^5.5.3",
    "vite": "^5.3.4",
    "vitest": "^2.0.4",
    "vue-tsc": "^2.0.26"
  }
}

import { fileURLToPath, URL } from 'node:url';
import { defineConfig } from 'vitest/config';
import vue from '@vitejs/plugin-vue';

export default defineConfig({
  plugins: [vue()],
  resolve: {
    alias: {
      '@': fileURLToPath(new URL('./src', import.meta.url)),
    },
  },
  server: { port: {port} },
  test: {
    environment: 'jsdom',
  },
});

import { createApp } from 'vue';
import { createPinia } from 'pinia';
import App from './App.vue';
import router from './router';

const app = createApp(App);
app.use(createPinia());
app.use(router);
app.mount('#app');

/// <reference types="vite/client" />

declare module '*.vue' {
  import type { DefineComponent } from 'vue';
  const component: DefineComponent<{}, {}, any>;
  export default component;
}

interface ImportMetaEnv {
  readonly VITE_API_BASE: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

import { createRouter, createWebHistory } from 'vue-router';
import type { RouteRecordRaw } from 'vue-router';
import DefaultLayout from '@/layouts/DefaultLayout.vue';

const routes: RouteRecordRaw[] = [
  {
    path: '/',
    component: DefaultLayout,
    children: [
      { path: '', name: 'dashboard', component: () => import('@/views/Dashboard.vue') },
      { path: 'users', name: 'user-list', component: () => import('@/views/UserList.vue') },
      { path: 'users/:id', name: 'user-detail', component: () => import('@/views/UserDetail.vue'), props: true },
      { path: 'settings', name: 'settings', component: () => import('@/views/Settings.vue') },
    ],
  },
  { path: '/login', name: 'login', component: () => import('@/views/Login.vue') },
  { path: '/:pathMatch(.*)*', name: 'not-found', component: () => import('@/views/NotFound.vue') },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

export default router;

import { defineStore } from 'pinia';
import { ref } from 'vue';
import type { User } from '@/types';

export const useUserStore = defineStore('user', () => {
  const currentUser = ref<User | null>(null);
  const users = ref<User[]>([]);

  function setCurrentUser(user: User | null): void {
    currentUser.value = user;
  }

  function setUsers(list: User[]): void {
    users.value = list;
  }

  return { currentUser, users, setCurrentUser, setUsers };
});

export const baseURL: string = import.meta.env.VITE_API_BASE || '{apiBase}';

export interface RequestOptions extends RequestInit {
  params?: Record<string, string | number>;
}

export async function request<T>(path: string, options: RequestOptions = {}): Promise<T> {
  const { params, ...init } = options;
  const query = params
    ? '?' + new URLSearchParams(
        Object.entries(params).map(([key, value]) => [key, String(value)]),
      ).toString()
    : '';
  const response = await fetch(`${baseURL}${path}${query}`, {
    headers: { 'Content-Type': 'application/json' },
    ...init,
  });
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status} ${path}`);
  }
  return (await response.json()) as T;
}

import { request } from '@/api/client';
import type { User } from '@/types';

export function fetchUsers(): Promise<User[]> {
  return request<User[]>('/users');
}

export function fetchUser(id: number): Promise<User> {
  return request<User>(`/users/${id}`);
}

export function createUser(payload: Omit<User, 'id'>): Promise<User> {
  return request<User>('/users', {
    method: 'POST',
    body: JSON.stringify(payload),
  });
}

export interface User {
  id: number;
  username: string;
  email: string;
}

export interface ApiResponse<T> {
  code: number;
  message: string;
  data: T;
}

import { describe, it, expect } from 'vitest';
import { mount } from '@vue/test-utils';
import Dashboard from '@/views/Dashboard.vue';

describe('Dashboard.vue', () => {
  it('renders the dashboard header', () => {
    const wrapper = mount(Dashboard);
    expect(wrapper.text()).toContain('Dashboard');
  });

  it('renders metric cards', () => {
    const wrapper = mount(Dashboard);
    expect(wrapper.findAll('.card').length).toBeGreaterThan(0);
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useUserStore } from '@/stores/user';

describe('user store', () => {
  beforeEach(() => {
    setActivePinia(createPinia());
  });

  it('starts with no current user', () => {
    const store = useUserStore();
    expect(store.currentUser).toBeNull();
  });

  it('stores the users list', () => {
    const store = useUserStore();
    store.setUsers([{ id: 1, username: 'demo', email: 'demo@example.com' }]);
    expect(store.users.length).toBe(1);
  });
});
